    static String profile(String value)throws IOException {if(!Set.of("source-def-anc","complete-def-anc").contains(value))throw new IOException("Explicit source-def-anc or complete-def-anc required; no method fallback");return value;}
    static List<Integer> children(Path stderr)throws IOException {
        String text=NextflowFiles.utf8(NextflowFiles.bytes(stderr,16777216));var matcher=Pattern.compile("(?m)^INFO: Process Exited with status: (-?[0-9]+)\\r?$").matcher(text);var codes=new ArrayList<Integer>();
        while(matcher.find())try{codes.add(Integer.parseInt(matcher.group(1)));}catch(NumberFormatException e){throw new IOException("Original child exit overflows",e);}
        if(!codes.equals(List.of(0,0))||text.contains("SEVERE")||text.contains("Exception in thread")||text.contains("OutOfMemoryError"))throw new IOException("Original HOPS child exits are not exactly two successes: "+codes+"; driver zero exit alone is insufficient; inspect "+stderr);
        return List.copyOf(codes);
    }
