        c.put("useSlurm",0);c.put("pathToMaltExtract",root+"/bundle/bin/MaltExtract");c.put("pathToPostProcessing",root+"/bundle/bin/postprocessing");c.put("pathToList",root+"/bundle/inputs/targets.txt");c.put("resources",root+"/bundle/inputs/resources");c.put("filter","def_anc");c.put("threadsMaltEx",caps.threads());c.put("maxMemoryMaltEx",caps.heapMib()/1024);c.put("threadsPost",caps.threads());c.put("maxMemoryPost",caps.heapMib()/1024);c.put("top","0.01");c.put("reads",1);c.put("alignment",1);c.put("useTopAlignment",0);
        int off=profile.equals("complete-def-anc")?1:0;for(String n:List.of("destackingOff","dupRemOff","downSampOff"))c.put(n,off);c.put("postStrictDamage",0);c.put("postDisplayAll",0);
