    static void originalErrors(Path original,MaltExtractWorkflowCli.Caps caps)throws IOException {
        try(var files=Files.list(original)) {
            for(Path p:files.filter(p->p.getFileName().toString().equals("error.txt")||p.getFileName().toString().startsWith("log.txt")).toList()) {
                NextflowFiles.pin(p,caps.fileBytes(),()->{});
                try(var reader=Files.newBufferedReader(p,StandardCharsets.UTF_8)) {
                    for(String line;(line=reader.readLine())!=null;) {
                        if(line.length()>10000000)throw new IOException("Original log line exceeds complete capacity");
                        if(line.contains("SEVERE")||line.contains("Exception in thread")||line.contains("OutOfMemoryError"))throw new IOException("Original extraction logged a fatal error despite possible zero exit: "+p.getFileName());
                    }
                }
            }
        }
    }
    private static void pdf(Path path,MaltExtractWorkflowCli.Caps caps)throws IOException {
        var pin=NextflowFiles.pin(path,caps.fileBytes(),()->{});if(pin.bytes()<100)throw new IOException("Truncated original PDF");
        try(var channel=Files.newByteChannel(path)) {
            var head=java.nio.ByteBuffer.allocate(8);while(head.hasRemaining())if(channel.read(head)<0)throw new IOException("Incomplete PDF header");
            if(!new String(head.array(),StandardCharsets.US_ASCII).startsWith("%PDF-1."))throw new IOException("Original PDF header differs");
            int count=(int)Math.min(pin.bytes(),2048);channel.position(pin.bytes()-count);var tail=java.nio.ByteBuffer.allocate(count);while(tail.hasRemaining())if(channel.read(tail)<0)throw new IOException("Incomplete PDF trailer");
            if(!new String(tail.array(),StandardCharsets.ISO_8859_1).stripTrailing().endsWith("%%EOF"))throw new IOException("Original PDF trailer absent");
        }
    }
